import argparse
from datetime import datetime
from pathlib import Path
import tempfile
import unittest

import config


def isolate_paths(directory):
    """Redirect all writable app paths before importing modules with default path arguments."""
    original = config.DATA_DIR
    # Course: U03 s2 – defaults bind at definition time, so configure before importing the app.
    for name, value in list(vars(config).items()):
        if isinstance(value, Path) and value.is_relative_to(original):
            if name != 'TAXONOMY_FILE':
                setattr(config, name, directory / value.relative_to(original))


def serve_api(arguments):
    """Run the real Flask app for the test using its temporary database and injected clock."""
    clock = datetime.fromisoformat(arguments[2])
    config.local_now = lambda now=None: now or clock
    # Delayed import is intentional: config must precede module-level default arguments.
    import api_server
    server = api_server.create_app(Path(arguments[0]))
    server.run(host='127.0.0.1', port=int(arguments[1]), debug=False,
               use_reloader=False, threaded=False)


def main():
    """Run one isolated acceptance test, returning a nonzero exit status on failure."""
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--api', nargs=3, metavar=('DATABASE', 'PORT', 'CLOCK'),
                        help=argparse.SUPPRESS)
    arguments = parser.parse_args()
    if arguments.api:
        serve_api(arguments.api)
        return 0
    with tempfile.TemporaryDirectory(prefix='weekwise-acceptance-') as directory:
        isolate_paths(Path(directory) / 'data')
        # Keep Streamlit imports inside views, as required by the UI dependency boundary.
        from views import demo_scenario
        suite = unittest.defaultTestLoader.loadTestsFromTestCase(demo_scenario.DemoScenario)
        result = unittest.TextTestRunner(verbosity=2).run(suite)
        return 0 if result.wasSuccessful() else 1


if __name__ == '__main__':
    raise SystemExit(main())
